const $=id=>document.getElementById(id),key='lightfield-v1',isOutput=new URLSearchParams(location.search).has('output');
const defaults={pattern:'rays',speed:.6,rotation:2,density:42,width:35,glow:65,brightness:100,fill:35,x:55,y:53,color1:'#42ff08',color2:'#13a600',color3:'#b6ff55',paused:matchMedia('(prefers-reduced-motion: reduce)').matches,blackout:false};
let state={...defaults};try{Object.assign(state,JSON.parse(localStorage.getItem(key)||'{}'))}catch{}
const looks={ 'Laser green':{...defaults},'Prism portrait':{pattern:'rays',speed:.22,rotation:.7,density:14,width:100,glow:88,brightness:100,fill:45,color1:'#00d9ff',color2:'#ffdc38',color3:'#f59dff'},'Ultraviolet':{pattern:'spiral',speed:.45,rotation:-1.5,density:26,width:80,glow:80,brightness:100,fill:35,color1:'#6622ff',color2:'#ff2b9b',color3:'#25c9ff'},'Amber haze':{pattern:'fan',speed:.18,rotation:.5,density:18,width:100,glow:90,brightness:100,fill:45,color1:'#ff680a',color2:'#ffca59',color3:'#f63d29'}};
let chosen='',controls=[],timer;function notice(t){$('status').textContent=t;clearTimeout(timer);timer=setTimeout(()=>$('status').textContent='',3000)}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{notice('Settings could not be saved in this browser.')}sync()}
function slider(parent,id,label,min,max,step,unit=''){const l=document.createElement('label');l.innerHTML=`<span class="row"><span>${label}</span><output></output></span><input aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}">`;$(parent).append(l);const input=l.querySelector('input'),out=l.querySelector('output');controls.push(()=>{input.value=state[id];out.textContent=Number(state[id]).toFixed(step<1?1:0)+unit});input.oninput=()=>{state[id]=Number(input.value);chosen='';save()}}
slider('sliders','speed','Flow speed',0,3,.1,'×');slider('sliders','rotation','Rotation',-12,12,.1,'°/s');slider('sliders','density','Beam count',6,90,1);slider('sliders','width','Beam width',10,100,1,'%');slider('lightSliders','glow','Softness',0,100,1,'%');slider('lightSliders','brightness','Brightness',0,100,1,'%');slider('lightSliders','fill','Background light',0,100,1,'%');slider('positionSliders','x','Horizontal',0,100,1,'%');slider('positionSliders','y','Vertical',0,100,1,'%');
for(const [name,look]of Object.entries(looks)){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{const {x,y,paused}=state;state={...state,...look,x,y,paused,blackout:false};chosen=name;save()};$('presets').append(b)}
for(const colors of [['#42ff08','#13a600','#b6ff55'],['#00d9ff','#ffdc38','#f59dff'],['#6622ff','#ff2b9b','#25c9ff'],['#ff680a','#ffca59','#f63d29'],['#ffffff','#7acfff','#c9dcff']]){const b=document.createElement('button');b.style.background=`linear-gradient(100deg,${colors.join(',')})`;b.setAttribute('aria-label','Palette '+colors.join(', '));b.onclick=()=>{[state.color1,state.color2,state.color3]=colors;chosen='';save()};$('palettes').append(b)}
for(const id of ['pattern','color1','color2','color3'])$(id).oninput=()=>{state[id]=$(id).value;chosen='';save()};
function sync(){controls.forEach(f=>f());for(const id of ['pattern','color1','color2','color3'])$(id).value=state[id];$('pause').textContent=state.paused?'Play':'Pause';$('pause').setAttribute('aria-pressed',String(state.paused));for(const b of $('presets').children)b.classList.toggle('active',b.textContent===chosen)}
$('pause').onclick=()=>{state.paused=!state.paused;save()};$('center').onclick=()=>{state.x=50;state.y=50;save()};
function clean(v){document.body.classList.toggle('clean',v);$('restore').hidden=!v||isOutput} $('hide').onclick=()=>clean(true);$('restore').onclick=()=>clean(false);
async function fullscreen(){clean(true);$('outputPrompt').hidden=true;try{await document.documentElement.requestFullscreen();document.body.classList.add('projecting');clean(true);$('outputPrompt').hidden=true}catch{notice('Fullscreen unavailable. Hide controls or use your browser’s fullscreen command.')}}
$('project').onclick=fullscreen;$('outputFull').onclick=fullscreen;$('output').onclick=()=>{save();const u=new URL(location.href);u.searchParams.set('output','1');const w=window.open(u,'lightfield-output','popup,width=1280,height=720');if(!w)notice('Allow popups to open the projector window.')};
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){document.body.classList.remove('projecting');if(isOutput)$('outputPrompt').hidden=false;else clean(false)}});
window.addEventListener('storage',e=>{if(e.key===key&&e.newValue){try{state={...defaults,...JSON.parse(e.newValue)};sync()}catch{}}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select')&&e.key!=='Escape')return;if(e.target.matches('button')&&e.code==='Space')return;if(e.code==='Space'){e.preventDefault();$('pause').click()}if(e.key.toLowerCase()==='h'&&!isOutput)clean(!document.body.classList.contains('clean'));if(e.key.toLowerCase()==='f')fullscreen();if(e.key.toLowerCase()==='b'){state.blackout=!state.blackout;save()}if(e.key==='Escape'&&!document.fullscreenElement&&!isOutput)clean(false)});
const canvas=$('light'),ctx=canvas.getContext('2d',{alpha:false});let W=0,H=0,flow=0,angle=0,last=0;
function resize(){const d=Math.min(devicePixelRatio||1,1.5);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();
let dragging=false;function point(e){state.x=Math.max(0,Math.min(100,e.clientX/W*100));state.y=Math.max(0,Math.min(100,e.clientY/H*100));save()}canvas.onpointerdown=e=>{if(isOutput)return;dragging=true;canvas.setPointerCapture(e.pointerId);point(e)};canvas.onpointermove=e=>{if(dragging)point(e)};canvas.onpointerup=canvas.onpointercancel=()=>dragging=false;
const rand=i=>{const n=Math.sin(i*127.1+44.7)*43758.5453;return n-Math.floor(n)};
function beam(a,span,length,color,alpha){ctx.save();ctx.rotate(a);const g=ctx.createLinearGradient(0,0,length,0);g.addColorStop(0,'#000');g.addColorStop(.12,color);g.addColorStop(1,color);ctx.fillStyle=g;ctx.globalAlpha=alpha;ctx.beginPath();ctx.moveTo(0,0);if(state.pattern==='spiral'){ctx.quadraticCurveTo(length*.45,length*.13-span*length*.4,length,-span*length);ctx.lineTo(length,span*length);ctx.quadraticCurveTo(length*.45,length*.13+span*length*.4,0,0)}else{ctx.lineTo(length,-span*length);ctx.lineTo(length,span*length)}ctx.closePath();ctx.fill();ctx.restore()}
function draw(now){const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(!state.paused&&!document.hidden){flow+=dt*state.speed;angle+=dt*state.rotation*Math.PI/180}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);if(!state.blackout){const wash=ctx.createLinearGradient(0,0,W,H);wash.addColorStop(0,state.color1);wash.addColorStop(.5,state.color2);wash.addColorStop(1,state.color3);ctx.globalAlpha=state.fill/100*state.brightness/100;ctx.fillStyle=wash;ctx.fillRect(0,0,W,H);ctx.globalAlpha=1;ctx.save();ctx.translate(W*state.x/100,H*state.y/100);ctx.globalCompositeOperation='screen';const radius=Math.hypot(W,H)*1.15,colors=[state.color1,state.color2,state.color3],count=state.density;for(let i=0;i<count;i++){const seed=rand(i),a=angle+(state.pattern==='fan'?(-Math.PI*.84+i/count*Math.PI*1.68):i/count*Math.PI*2)+(seed-.5)*.075+Math.sin(flow*.45+seed*20)*.035+(state.pattern==='spiral'?Math.sin(flow*.32+i*.3)*.23:0);const width=(.003+seed*.019)*(state.width/35)*(42/count),power=(.65+.35*(.5+.5*Math.sin(flow*1.4+seed*40)))*state.brightness/100;const c=colors[i%3];for(let layer=18;layer>=1;layer--){const t=layer/18,spread=.08+t*t*(1+state.glow/50);beam(a,width*spread,radius,c,power*(.12+(1-t)*.15))}}ctx.restore()}requestAnimationFrame(draw)}
if(isOutput){clean(true);$('outputPrompt').hidden=false}sync();requestAnimationFrame(draw);
